    /// Upon receipt, this SHALL change the input on the media device to the input at a specific index in the Input
    /// List.
    #[derive(Debug, Clone, PartialEq, Eq, Hash, Default)]
    #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
    #[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
    #[cfg_attr(all(feature = "serde", feature = "deny-unknown-fields"), serde(deny_unknown_fields))]
    #[cfg_attr(
        all(feature = "schemars", feature = "deny-unknown-fields"),
        schemars(deny_unknown_fields)
    )]
    pub struct SelectInput {
        pub index: u8,
    }

    impl SelectInput {
        pub const CLUSTER_ID: ClusterId = super::MediaInputCluster::CLUSTER_ID;
        pub const COMMAND_ID: CommandId = CommandId::new(0x00);
        pub const DIRECTION: CommandDirection = CommandDirection::ClientToServer;
        pub const FIELD_INDEX: FieldId = FieldId::new(0x0);
        pub const NAME: &'static str = "SelectInput";

        #[must_use]
        pub fn new(index: impl Into<u8>) -> Self {
            Self { index: index.into() }
        }

        #[must_use]
        pub fn into_fields(self) -> Vec<(FieldId, AttributeValue)> {
            alloc::vec![(Self::FIELD_INDEX, AttributeValue::from(self.index)),]
        }

        pub(crate) fn decode_fields(
            fields: Vec<(FieldId, AttributeValue)>,
        ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
            let mut index = None;
            for (fid, fval) in fields {
                if fid.raw() == 0 {
                    if index.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    (|| -> Result<(), MatterStatus> {
                        let decoded = crate::traits::decode_scalar::<u8>(&fval)?;
                        index = Some(decoded);
                        Ok(())
                    })()
                    .map_err(|status| (Some(fid), status))?;
                } else {
                    return Err((Some(fid), MatterStatus::ConstraintError));
                }
            }
            Ok(Self {
                index: index.ok_or((Some(FieldId::new(0)), MatterStatus::InvalidCommand))?,
            })
        }
    }

    impl From<u8> for SelectInput {
        #[inline]
        fn from(val: u8) -> Self {
            Self::new(val)
        }
    }

    crate::impl_matter_command!(SelectInput, super::MediaInputCluster, (), false);

