    /// Upon receipt, this SHALL rename the input at a specific index in the Input List. Updates to the input name SHALL
    /// appear in the TV settings menus.
    #[derive(Debug, Clone, PartialEq, Eq, Hash, Default)]
    #[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
    #[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
    #[cfg_attr(all(feature = "serde", feature = "deny-unknown-fields"), serde(deny_unknown_fields))]
    #[cfg_attr(
        all(feature = "schemars", feature = "deny-unknown-fields"),
        schemars(deny_unknown_fields)
    )]
    pub struct RenameInput {
        pub index: u8,
        pub name: String,
    }

    impl RenameInput {
        pub const CLUSTER_ID: ClusterId = super::MediaInputCluster::CLUSTER_ID;
        pub const COMMAND_ID: CommandId = CommandId::new(0x03);
        pub const DIRECTION: CommandDirection = CommandDirection::ClientToServer;
        pub const FIELD_INDEX: FieldId = FieldId::new(0x0);
        pub const FIELD_NAME: FieldId = FieldId::new(0x1);
        pub const NAME: &'static str = "RenameInput";

        #[must_use]
        pub fn new(index: impl Into<u8>, name: impl Into<String>) -> Self {
            Self {
                index: index.into(),
                name: name.into(),
            }
        }

        #[must_use]
        pub fn into_fields(self) -> Vec<(FieldId, AttributeValue)> {
            alloc::vec![
                (Self::FIELD_INDEX, AttributeValue::from(self.index)),
                (Self::FIELD_NAME, AttributeValue::from(self.name)),
            ]
        }

        pub(crate) fn decode_fields(
            fields: Vec<(FieldId, AttributeValue)>,
        ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
            let mut index = None;
            let mut name = None;
            for (fid, fval) in fields {
                match fid.raw() {
                    0 => {
                        if index.is_some() {
                            return Err((Some(fid), MatterStatus::ConstraintError));
                        }
                        (|| -> Result<(), MatterStatus> {
                            let decoded = crate::traits::decode_scalar::<u8>(&fval)?;
                            index = Some(decoded);
                            Ok(())
                        })()
                        .map_err(|st| (Some(fid), st))?;
                    }
                    1 => {
                        if name.is_some() {
                            return Err((Some(fid), MatterStatus::ConstraintError));
                        }
                        (|| -> Result<(), MatterStatus> {
                            let decoded = <String>::try_from(fval)?;
                            name = Some(decoded);
                            Ok(())
                        })()
                        .map_err(|st| (Some(fid), st))?;
                    }
                    _ => return Err((Some(fid), MatterStatus::ConstraintError)),
                }
            }
            Ok(Self {
                index: index.ok_or((Some(FieldId::new(0)), MatterStatus::InvalidCommand))?,
                name: name.ok_or((Some(FieldId::new(1)), MatterStatus::InvalidCommand))?,
            })
        }
    }

